import 'package:flutter/material.dart';

/// Fixed colors that are not generated by the Material 3 seed.
/// Status colors are defined once here and reused everywhere.
class AppColors {
  AppColors._();

  /// Seed color: M3 builds the whole palette from this one color.
  static const Color seed = Color(0xFF00796B);

  // Report status colors (match the Figma Foundations page).
  static const Color submitted = Color(0xFF757575);
  static const Color underReview = Color(0xFFF9A825);
  static const Color inProgress = Color(0xFF1976D2);
  static const Color resolved = Color(0xFF2E7D32);
}
